insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('CN', 'default', '企业会计准则 会计科目（节选）— Accounts of the Accounting Standards for Business Enterprises, abridged', '{"en":"Accounts of the Accounting Standards for Business Enterprises (abridged)"}'::jsonb, true, 'companies', array['CN-ASBE-BS', 'CN-ASBE-IS']::text[], null, '《企业会计准则——应用指南》（财会〔2006〕18号）附录《会计科目和主要账务处理》 — the first-level accounts and their four-digit codes are transcribed from the appendix, leaving out those of banks, insurers and securities firms, and 6403 carries the name 税金及附加 that 财会〔2016〕22号 gave 营业税金及附加. The appendix lets an enterprise add, split or merge accounts and set its own detail accounts and numbers ("对于明细科目，企业可以比照本附录中的规定自行设置。会计科目编号供企业…参考，企业可结合实际情况自行确定会计科目编号"): the detail accounts of 应付职工薪酬, 盈余公积, 利润分配 and 所得税费用 are the ones the appendix names for them; those of 应交税费 are the ones 财会〔2016〕22号 prescribes; the columns (专栏) of 应交增值税 are carried as accounts 22210101 to 22210110 beside 222101, which the same rule gives a small-scale taxpayer as its one VAT account. Four codes are this pack''s own, for accounts later standards introduced and the 2006 appendix does not number: 6115 资产处置损益, 6117 其他收益, 6702 信用减值损失, and the six-digit expense details of 销售费用, 管理费用 and 财务费用. See the README.', 'asbe-guide')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

