insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CN', 'CN-VAT-GENERAL', '增值税及附加税费申报表（一般纳税人适用） — VAT and surcharges return, general taxpayer, main table', array['month', 'quarter']::declaration_period[], null, date '2026-01-01', null, '中华人民共和国增值税法第三十条 — the taxable period is ten days, fifteen days, one month or one quarter, fixed for each taxpayer by the competent tax office according to the amount of tax it owes; 增值税法实施条例第四十三条 limits the quarter to small-scale taxpayers, banks, finance companies, trust companies and credit cooperatives among general taxpayers, and whoever the State Council''s tax and finance authorities add. This pack carries the month and the quarter, and proposes neither: the period is assigned by the tax office, not chosen. The form is the main table of 增值税及附加税费申报表（一般纳税人适用）, issued by 国家税务总局公告2021年第20号 and still in use, with the filling instructions 国家税务总局公告2026年第6号 adjusts for the VAT Law ("增值税纳税人暂使用《增值税及附加税费申报表（一般纳税人适用）》及其附列资料…有关栏次按本公告调整后的填报要求填写"). Its four schedules and the surcharge lines 39 to 41 are not modelled; see the README. Amounts are in yuan to the fen ("金额单位：元（列至角分）"), so the form carries no rounding of its own.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, '中华人民共和国增值税法第三十条第二款 — a taxpayer on a one-month or one-quarter period files and pays within fifteen days of its end ("自期满之日起十五日内申报纳税"). A deadline falling on a public holiday is moved by the State Taxation Administration''s yearly filing calendar, which this rule does not know.', 'vat-law', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('CN', 'CN-VAT-GENERAL', '2', 'base', '其中：应税货物销售额', '{"en":"of which: sales of taxable goods"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第2栏 — the sales of taxable goods at an applicable rate, a part of line 1.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '3', 'base', '应税劳务销售额', '{"en":"sales of taxable services"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第3栏 — as redefined by 国家税务总局公告2026年第6号 附件1: the sales of taxable services (including processing, repair and replacement services), intangible assets and immovable property at an applicable rate, a part of line 1.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '1', 'total', '（一）按适用税率计税销售额', '{"en":"(1) Sales taxed at an applicable rate"}'::jsonb, 30, 5, array['2', '3']::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第1栏 — the sales taxed at an applicable rate. Line 1 is lines 2 and 3 plus line 4 (纳税检查调整的销售额, adjustments found by a tax inspection), which is not a fact of the ledger and is not declared here.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '5', 'base', '（二）按简易办法计税销售额', '{"en":"(2) Sales taxed on the simplified method"}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第5栏 — the sales taxed on the simplified method (line 6, the inspection adjustment inside it, is not declared).', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '7', 'base', '（三）免、抵、退办法出口销售额', '{"en":"(3) Export sales under the exemption-credit-refund method"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第7栏 — the export sales declared under the exemption-credit-refund method.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '9', 'base', '其中：免税货物销售额', '{"en":"of which: exempt sales of goods"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第9栏 — the sales of exempt goods, a part of line 8.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '10', 'base', '免税劳务销售额', '{"en":"exempt sales of services"}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第10栏 — as redefined by 国家税务总局公告2026年第6号 附件1: the exempt and zero-rated sales of services, intangible assets and immovable property, excluding zero-rated sales under the exemption-credit-refund method.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '8', 'total', '（四）免税销售额', '{"en":"(4) Exempt sales"}'::jsonb, 80, 55, array['9', '10']::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第8栏 — lines 9 and 10, the exempt sales.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '11', 'tax', '销项税额', '{"en":"Output tax"}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第11栏 — the output tax of the period.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '12', 'tax', '进项税额', '{"en":"Input tax"}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第12栏 — the input tax of the period, from the deduction vouchers the buyer has confirmed for deduction.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '17', 'total', '应抵扣税额合计', '{"en":"Total deductible tax"}'::jsonb, 110, null, array['12']::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第17栏 — printed as 12+13-14-15+16. Line 13 (上期留抵税额, the credit carried in from the previous period) is what the previous return came to and not a fact this period''s ledger holds; line 14 (进项税额转出), line 15 (免、抵、退应退税额) and line 16 (纳税检查应补缴税额) come from procedures this pack does not model. This pack therefore declares line 17 as line 12 alone; see the README.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '19', 'total', '应纳税额', '{"en":"Tax payable"}'::jsonb, 120, null, array['11']::text[], array['17']::text[], null, null, true, false, null, '增值税及附加税费申报表（一般纳税人适用），第19栏 — printed as 11-18. Line 18 is 17 where 17 is below 11 and 11 otherwise, so 11-18 is 11-17 floored at zero, which is how it is computed here.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '18', 'total', '实际抵扣税额', '{"en":"Tax actually deducted"}'::jsonb, 130, 115, array['11']::text[], array['19']::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第18栏 — printed as "如17<11，则为17，否则为11", the smaller of lines 17 and 11. The format has no minimum; 11 less line 19 is that minimum, whichever of the two is smaller.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '20', 'total', '期末留抵税额', '{"en":"Credit carried forward at the end of the period"}'::jsonb, 140, null, array['17']::text[], array['11']::text[], null, null, true, false, null, '增值税及附加税费申报表（一般纳税人适用），第20栏 — printed as 17-18: the input tax left over, carried to the next period''s line 13 (or refunded under article 21 of 中华人民共和国增值税法). Computed as 17-11 floored at zero, which is the same figure.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '21', 'tax', '简易计税办法计算的应纳税额', '{"en":"Tax payable on the simplified method"}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第21栏 — the tax computed on the simplified method.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '24', 'total', '应纳税额合计', '{"en":"Total tax payable"}'::jsonb, 160, null, array['19', '21']::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第24栏 — printed as 19+21-23; line 23 (应纳税额减征额, reductions such as the tax-control equipment credit) is not modelled.', 'form-general'),
  ('CN', 'CN-VAT-GENERAL', '34', 'total', '本期应补(退)税额', '{"en":"Tax to pay (refund) this period"}'::jsonb, 170, null, array['24']::text[], '{}'::text[], null, null, false, false, null, '增值税及附加税费申报表（一般纳税人适用），第34栏 — printed as 24-28-29, the tax to pay this period net of the instalments prepaid during it (line 28, 分次预缴税额) and of the tax prepaid on special export payment books (line 29). Neither is booked by a tax code of this pack, so line 34 comes to line 24.', 'form-general')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
