  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('CN-ASBE-BS', 'CN', 'default', '资产负债表（会企01表）— Balance sheet', 'balance_sheet', '企业会计准则', date '1970-01-01', null, '财政部关于修订印发2019年度一般企业财务报表格式的通知（财会〔2019〕6号）附件2 — the balance sheet 会企01表 of a non-financial enterprise that applies the new financial instruments, revenue and leases standards. The notice itself lets an enterprise leave out the items it has no business for ("企业对不存在相应业务的报表项目可结合本企业的实际情况进行必要删减"); this statement leaves out the items this chart carries no account for — 衍生金融资产, 应收款项融资, 合同资产, 持有待售资产, 一年内到期的非流动资产, 债权投资, 其他债权投资, 其他权益工具投资, 其他非流动金融资产, 油气资产, 使用权资产, 其他非流动资产 and their liability and equity counterparts (衍生金融负债, 合同负债, 持有待售负债, 一年内到期的非流动负债, 租赁负债, 其他非流动负债, 其他权益工具, 其他综合收益, 专项储备). Line codes are this pack''s own: the form numbers no line.', 'fs-format'),
  ('CN-ASBE-IS', 'CN', 'default', '利润表（会企02表）— Income statement', 'income_statement', '企业会计准则', date '1970-01-01', null, '财会〔2019〕6号 附件2 — the income statement 会企02表, down to 四、净利润. The 其中 lines under 财务费用 (利息费用, 利息收入) and 投资收益, the split of net profit between continuing and discontinued operations, other comprehensive income (五), total comprehensive income (六) and earnings per share (七) are not carried: this chart has no account for other comprehensive income, and the 其中 lines restate a part of a line already printed.', 'fs-format')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

