  ('CN-ASBE-BS', 'A01', null, '货币资金', '{"en":"Cash and cash equivalents"}'::jsonb, 10, 1, false, '{}'::text[], '{}'::text[], null, null, null),
  ('CN-ASBE-BS', 'A02', null, '交易性金融资产', '{"en":"Financial assets held for trading"}'::jsonb, 20, 1, false, '{}'::text[], '{}'::text[], null, null, null),
