  ('CN-ASBE-BS', 'A13', null, '其他流动资产', '{"en":"Other current assets"}'::jsonb, 80, 1, false, '{}'::text[], '{}'::text[], null, '财会〔2016〕22号 — the debit balances of 应交增值税, 未交增值税, 待抵扣进项税额, 待认证进项税额, 增值税留抵税额 and the other detail accounts of 应交税费 are presented under 其他流动资产 ("期末借方余额应根据情况，在资产负债表中的''其他流动资产''或''其他非流动资产''项目列示").', null),
  ('CN-ASBE-BS', 'A14', null, '流动资产合计', '{"en":"Total current assets"}'::jsonb, 90, 1, true, array['A01', 'A02', 'A04', 'A05', 'A07', 'A08', 'A09', 'A13']::text[], '{}'::text[], null, null, null),
