update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = '国家税务总局公告2024年第11号 第四条 — the number of a fully digitalised invoice is twenty digits, assigned nationwide by the tax authority''s platform ("号码全国统一赋予"): two for the year, two for the provincial tax bureau, one for the issuing channel and fifteen of sequence. The seller does not choose it and Ekwo does not draw it; the number above is the internal reference of the document in the books, and the invoice number the platform returns is a fact to record beside it. See the README.',
  numbering_source_key          = 'einvoice-2024-11',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = '中华人民共和国增值税法第二十八条第一款第一项 — the VAT obligation arises on the day the sale proceeds are received or the right to claim them is obtained ("收讫销售款项或者取得销售款项索取凭据的当日"), or on the day the invoice is issued where it is issued first ("先开具发票的，为开具发票的当日"). The first two branches are the earliest of a payment and of the right to payment, which ordinarily arises with the supply; the third, an invoice issued before either, is not a word of this vocabulary and makes the tax due on the invoice date. 增值税法实施条例第四十一条 moves an export to the day of the customs declaration where it comes first.',
  tax_point_source_key          = 'vat-law',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = '国家税务总局公告2024年第11号 第八条 — once issued, a digital invoice is corrected, for a return, an error, an interrupted service or a price allowance, by a red-letter invoice (红字数电发票) and never by editing it; 增值税法实施条例 also bars reducing output tax or sales for a special invoice that has not been voided or reversed in the prescribed way. A posted document is therefore undone by a credit note.',
  posted_edit_policy_source_key = 'einvoice-2024-11',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No statute obliges a Chinese business to exchange a structured invoice under EN 16931 or a Peppol profile with its trading partner: there is no Peppol Authority for China, and none of peppol-bis-3, factur-x-en16931, xrechnung or a PINT applies. This is a null answer to a European-shaped question and not a statement that China has no electronic invoicing — the opposite is true. 中华人民共和国增值税法第三十四条 requires invoices to be issued according to law and gives the electronic invoice the paper one''s legal force; 国家税务总局公告2024年第11号 generalised the fully digitalised invoice (数电发票) from 1 December 2024: issued on the tax authority''s own platform, numbered by it, capped by a monthly invoicing limit the authority grants, delivered to the buyer''s tax digital account, and confirmed there by the buyer before its tax can be deducted. That is a real-time clearance model the pack format cannot express; see the README and docs/international.md, "From China".',
  einvoice_source_key           = 'einvoice-2024-11',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'CN';
